    severity: { en: 'Severity', es: 'Severidad', tl: 'Kalubhaan', vi: 'Mức Độ Nghiêm Trọng', ko: '심각도' },
    severe: { en: 'Severe', es: 'Severo', tl: 'Malubha', vi: 'Nghiêm Trọng', ko: '심각' },
