    nexusTheory: { en: 'Nexus Theory', es: 'Teoría de Nexo', tl: 'Nexus Theory', vi: 'Lý Thuyết Nexus', ko: '넥서스 이론' },
    connectionType: { en: 'Connection Type', es: 'Tipo de Conexión', tl: 'Uri ng Koneksyon', vi: 'Loại Kết Nối', ko: '연결 유형' },
